const inputItems = $input.all();
const chunks = [];

for (const inputItem of inputItems) {
  const markdown = inputItem.json.markdown;

  if (!markdown) {
    throw new Error('No markdown content found.');
  }

  const frontMatterMatch = markdown.match(
    /^---\s*\n([\s\S]*?)\n---\s*\n?/
  );

  if (!frontMatterMatch) {
    throw new Error(
      `No YAML front matter found in ${inputItem.json.fileName ?? 'unknown file'}`
    );
  }

  const metadata = {};

  for (const line of frontMatterMatch[1].split('\n')) {
    const separatorIndex = line.indexOf(':');

    if (separatorIndex === -1) continue;

    const key = line.slice(0, separatorIndex).trim();
    const value = line.slice(separatorIndex + 1).trim();

    metadata[key] = value;
  }

  const body = markdown
    .replace(frontMatterMatch[0], '')
    .trim();

  const sections = body
    .split(/(?=^#{1,3}\s+)/gm)
    .map(section => section.trim())
    .filter(Boolean);

  let chunkIndex = 0;

  const addChunk = content => {
    chunks.push({
      json: {
        source_id: metadata.source_id,
        organisation: metadata.organisation,
        topic: metadata.topic,
        source_title: metadata.source_title,
        source_url: metadata.source_url,
        language: metadata.language,
        status: metadata.status,
        retrieved_at: metadata.retrieved_at,
        last_verified: metadata.last_verified,
        chunk_index: chunkIndex,
        content,
      },
    });

    chunkIndex++;
  };

  for (const section of sections) {
    if (section.length <= 900) {
      addChunk(section);
      continue;
    }

    const paragraphs = section
      .split(/\n\s*\n/)
      .map(paragraph => paragraph.trim())
      .filter(Boolean);

    let currentChunk = '';

    for (const paragraph of paragraphs) {
      const proposedChunk = currentChunk
        ? `${currentChunk}\n\n${paragraph}`
        : paragraph;

      if (proposedChunk.length > 900 && currentChunk) {
        addChunk(currentChunk);
        currentChunk = paragraph;
      } else {
        currentChunk = proposedChunk;
      }
    }

    if (currentChunk) {
      addChunk(currentChunk);
    }
  }
}

return chunks;

const inputItems = $input.all();
const results = [];

for (let index = 0; index < inputItems.length; index++) {
  const buffer = await this.helpers.getBinaryDataBuffer(index, 'data');
  const markdown = buffer.toString('utf8');

  const binaryInfo = inputItems[index].binary?.data;

  results.push({
    json: {
      fileName: binaryInfo?.fileName ?? `file-${index}.md`,
      mimeType: binaryInfo?.mimeType ?? 'text/markdown',
      markdown,
    },
  });
}

return results;

const embeddingItems = $input.all();
const chunkItems = $('Parse Metadata and Chunk').all();

if (embeddingItems.length !== chunkItems.length) {
  throw new Error(
    `Item count mismatch: ${embeddingItems.length} embeddings and ${chunkItems.length} chunks`
  );
}

return embeddingItems.map((embeddingItem, index) => {
  const chunk = chunkItems[index].json;
  const embedding = embeddingItem.json.embeddings?.[0];

  if (!Array.isArray(embedding) || embedding.length !== 768) {
    throw new Error(`Invalid embedding for chunk ${index}`);
  }

  return {
    json: {
      ...chunk,
      embedding,
    },
  };
});
